function patternHollowPyramid(n) {
  let rows = [];
  for (let i = 0; i < n; i++) {
    let row = '';
    for (let j = 0; j < n - 1 - i; j++) row += ' ';
    if (i === 0) {
      row += '*';
    } else if (i === n - 1) {
      for (let k = 0; k < 2 * n - 1; k++) row += '*';
    } else {
      row += '*';
      for (let k = 0; k < 2 * i - 1; k++) row += ' ';
      row += '*';
    }
    rows.push(row);
  }
  return rows.join('\n');
}

