function patternHollowPyramid(n) {
  let rows = [];
  for (let i = 0; i < n; i++) {
    if (i === 0) {
      rows.push(' '.repeat(n - 1) + '*');
    } else if (i === n - 1) {
      rows.push('*'.repeat(2 * n - 1));
    } else {
      const leading = ' '.repeat(n - 1 - i);
      const inner = ' '.repeat(2 * i - 1);
      rows.push(leading + '*' + inner + '*');
    }
  }
  return rows.join('\n');
}
